/*! \brief define for efficient programming of CSI2RX_CTRL CSI2 lane config registers */
#define CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE  \
                                   (CSL_CSI2RX_CTRL_RSS_CSI2A_LANE1_CFG - \
                                    CSL_CSI2RX_CTRL_RSS_CSI2A_LANE0_CFG)

/*! \brief check assumption of constancy of \ref CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE */
#if ( (CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE  != (CSL_CSI2RX_CTRL_RSS_CSI2A_LANE2_CFG -    \
                                         CSL_CSI2RX_CTRL_RSS_CSI2A_LANE1_CFG)) || \
      (CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE  != (CSL_CSI2RX_CTRL_RSS_CSI2A_LANE3_CFG -    \
                                         CSL_CSI2RX_CTRL_RSS_CSI2A_LANE2_CFG)) || \
      (CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE  != (CSL_CSI2RX_CTRL_RSS_CSI2A_LANE4_CFG -    \
                                         CSL_CSI2RX_CTRL_RSS_CSI2A_LANE3_CFG)) \
     )
#error CSL_CSI2RX_CTRL_CSI2RX_INTER_LANE_CFG_ADDR_DISTANCE assumption violated
#endif

/*! \brief define for efficient programming of CSI2RX_CTRL CSI2 line ping-pong context
       registers across contexts. */
